-- demo-15: "Cazul ceasului din gară" by blocker
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001500000000'::uuid, '00000000-0000-4000-8000-000000000015'::uuid, 'cazul-ceasului-din-gara-demo-15',
  $demo$Cazul ceasului din gară$demo$, $demo$În fiecare dimineață, ceasul mare din Halta Pădureni rămâne în urmă cu exact șapte minute, deși seara e potrivit la secundă. Șeful de haltă dă vina pe mecanism, pe frig și pe stăncuțe. Dora, unsprezece ani, nu crede în stăncuțe care știu să citească ceasul. Cu o lanternă și cu cățelul gării, se hotărăște să stea de pază o noapte întreagă.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, 'all_ages', 'no_ai',
  now() - interval '16 days', now() - interval '10 days', now() - interval '18 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001500000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001500000000'::uuid, '00000000-0000-4000-8000-000000000015'::uuid, array['mister', 'gară', 'ceas', 'tren de noapte', 'câine']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
