-- demo-16: "Ce aud blocurile la trei dimineața" by tudor_farasomn
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001600000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, 'ce-aud-blocurile-la-trei-dimineata-demo-16',
  $demo$Ce aud blocurile la trei dimineața$demo$, $demo$Trei eseuri scrise între două și cinci dimineața, de un om care n-a mai dormit o noapte întreagă de douăsprezece ani. Despre vecinul de deasupra care umbla în fiecare noapte și apoi s-a oprit, despre liftul care se cheamă singur și despre ce înseamnă, de fapt, să stai treaz într-o clădire în care toți ceilalți dorm. Nu e o carte de sfaturi. E un raport de la fața locului.$demo$, 'ro',
  (select id from public.categories where slug = 'nonfiction_essays'),
  'automatic', null, null, null, '16_plus', 'no_ai',
  now() - interval '53 days', now() - interval '47 days', now() - interval '55 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001600000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001600000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, array['insomnie', 'noapte', 'bloc', 'vecini', 'singurătate', 'eseu']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001600010000'::uuid, '00000000-0000-4000-9100-001600000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid,
  'd016c001', 1, $demo$Capitolul 1: Pașii de deasupra$demo$, public.check_chapter_text($demo$Nu știu când am început să nu mai dorm. Știu doar că la un moment dat somnul a devenit un vecin cu care mă salut pe scară și care nu mă mai invită înăuntru. Vine pe la unu, pleacă pe la trei, și între trei și cinci sunt singur cu blocul.

Blocul are sunete. Ziua nu le auzi, pentru că ziua e plin de oameni care fac zgomot cu rost. Noaptea rămân doar sunetele fără rost, cele pe care le face clădirea singură: țevile care se strâng când se răcește apa, un geam care vibrează la camionul de la patru, frigiderul care pornește și se oprește ca un animal care sforăie. Și pașii.

Deasupra mea locuia un om pe care nu l-am văzut niciodată la față. Știu că era bărbat după pași. Erau grei, răbdători, în papuci. Pornea pe la două și jumătate, de la fereastră spre ușă, de la ușă spre fereastră, cam cincisprezece pași în fiecare direcție. Am numărat. Când nu dormi, numeri; e singurul lucru pe care îl poți face cu o minte care refuză să se închidă.

Umbla cam o oră. Apoi se oprea, și eu știam că s-a așezat, pentru că auzeam arcul unui fotoliu bătrân. Apoi nimic. Apoi, la cinci, chiuveta.

Nu l-am urât niciodată. Dimpotrivă. În al treilea an de insomnie, pașii lui au devenit singura dovadă că nu sunt ultimul om treaz din oraș. Erau un fel de companie, cum e compania unui far pe care-l vezi de pe mal: nu te ajută cu nimic, dar e acolo, și clipește, și înseamnă că cineva a hotărât ca lumina să nu se stingă.

Într-o noapte de februarie, pașii n-au mai venit. Am stat cu ochii în tavan de la două și jumătate la trei, la patru, la cinci. La cinci n-a curs apa. M-am ridicat în capul oaselor și m-am gândit, cu o claritate care vine numai la ora aia: a murit.

N-a murit. Am aflat după două săptămâni, de la administratoare, că omul plecase la fiica lui, la țară, pentru că nu mai putea sta singur. Mi-a zis și numele, și l-am uitat imediat, cu grijă, ca pe o informație pe care n-am dreptul s-o am.

Dar în cele două săptămâni în care am crezut că e mort deasupra mea, am învățat ceva despre tăcere. Tăcerea nu e lipsa sunetului. Tăcerea e un sunet care a fost și nu mai e. Blocul nu devenise mai liniștit. Devenise mai gol, și golul, la trei dimineața, are un volum al lui.

Acum deasupra stă o familie cu un copil care plânge la patru. Îl aud. Îl ascult. Nu mă deranjează. Mă gândesc uneori că, dacă ar fi să dispară și el, m-ar durea la fel. Nu știu ce spune asta despre mine. Știu doar că, de când nu mai dorm, iubesc oamenii după sunetele pe care le fac prin tavan.$demo$), 1,
  now() - interval '53 days', $demo$Capitolul 1: Pașii de deasupra$demo$, public.check_chapter_text($demo$Nu știu când am început să nu mai dorm. Știu doar că la un moment dat somnul a devenit un vecin cu care mă salut pe scară și care nu mă mai invită înăuntru. Vine pe la unu, pleacă pe la trei, și între trei și cinci sunt singur cu blocul.

Blocul are sunete. Ziua nu le auzi, pentru că ziua e plin de oameni care fac zgomot cu rost. Noaptea rămân doar sunetele fără rost, cele pe care le face clădirea singură: țevile care se strâng când se răcește apa, un geam care vibrează la camionul de la patru, frigiderul care pornește și se oprește ca un animal care sforăie. Și pașii.

Deasupra mea locuia un om pe care nu l-am văzut niciodată la față. Știu că era bărbat după pași. Erau grei, răbdători, în papuci. Pornea pe la două și jumătate, de la fereastră spre ușă, de la ușă spre fereastră, cam cincisprezece pași în fiecare direcție. Am numărat. Când nu dormi, numeri; e singurul lucru pe care îl poți face cu o minte care refuză să se închidă.

Umbla cam o oră. Apoi se oprea, și eu știam că s-a așezat, pentru că auzeam arcul unui fotoliu bătrân. Apoi nimic. Apoi, la cinci, chiuveta.

Nu l-am urât niciodată. Dimpotrivă. În al treilea an de insomnie, pașii lui au devenit singura dovadă că nu sunt ultimul om treaz din oraș. Erau un fel de companie, cum e compania unui far pe care-l vezi de pe mal: nu te ajută cu nimic, dar e acolo, și clipește, și înseamnă că cineva a hotărât ca lumina să nu se stingă.

Într-o noapte de februarie, pașii n-au mai venit. Am stat cu ochii în tavan de la două și jumătate la trei, la patru, la cinci. La cinci n-a curs apa. M-am ridicat în capul oaselor și m-am gândit, cu o claritate care vine numai la ora aia: a murit.

N-a murit. Am aflat după două săptămâni, de la administratoare, că omul plecase la fiica lui, la țară, pentru că nu mai putea sta singur. Mi-a zis și numele, și l-am uitat imediat, cu grijă, ca pe o informație pe care n-am dreptul s-o am.

Dar în cele două săptămâni în care am crezut că e mort deasupra mea, am învățat ceva despre tăcere. Tăcerea nu e lipsa sunetului. Tăcerea e un sunet care a fost și nu mai e. Blocul nu devenise mai liniștit. Devenise mai gol, și golul, la trei dimineața, are un volum al lui.

Acum deasupra stă o familie cu un copil care plânge la patru. Îl aud. Îl ascult. Nu mă deranjează. Mă gândesc uneori că, dacă ar fi să dispară și el, m-ar durea la fel. Nu știu ce spune asta despre mine. Știu doar că, de când nu mai dorm, iubesc oamenii după sunetele pe care le fac prin tavan.$demo$), 'published',
  now() - interval '53 days', now() - interval '53 days', public.count_words($demo$Nu știu când am început să nu mai dorm. Știu doar că la un moment dat somnul a devenit un vecin cu care mă salut pe scară și care nu mă mai invită înăuntru. Vine pe la unu, pleacă pe la trei, și între trei și cinci sunt singur cu blocul.

