select '00000000-0000-4000-9100-001700000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, 'jurnal-de-paznic-de-noapte-demo-17',
  $demo$Jurnal de paznic de noapte$demo$, $demo$Un an întreg am păzit, de la zece seara la șase dimineața, un depozit de mobilă la marginea unui oraș în care nu mă cunoștea nimeni. Trei eseuri despre ce face un loc construit pentru oameni atunci când oamenii pleacă: despre câinele care nu trecea de raionul șapte, despre telefonul care a sunat dinăuntru și despre de ce inventăm fantome când nu suportăm golul.$demo$, 'ro',
  (select id from public.categories where slug = 'nonfiction_essays'),
  'drawn', 'twotone', 'plum', 'paper', '16_plus', 'no_ai',
  now() - interval '90 days', now() - interval '84 days', now() - interval '92 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001700000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001700000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, array['noapte', 'paznic', 'depozit', 'frică', 'eseu', 'singurătate']);
update public.stories
set cover_kind = 'drawn', cover_design = 'twotone', cover_background = 'plum', cover_accent = 'paper'
where stories.id = '00000000-0000-4000-9100-001700000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'twotone', 'plum', 'paper');
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001700010000'::uuid, '00000000-0000-4000-9100-001700000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid,
  'd017c001', 1, $demo$Capitolul 1: Raionul șapte$demo$, public.check_chapter_text($demo$Depozitul avea douăzeci de mii de metri pătrați, nouă raioane, un birou cu geam spre hală, un ceainic și un câine. Câinele se numea Rex, pentru că oamenii care numesc câini de pază nu au niciodată imaginație, și era un ciobănesc bătrân, cu un șold prost, care mă conducea în fiecare noapte prin toate raioanele, în ordine, cu o seriozitate de funcționar.

Toate raioanele în afară de șapte.

La capătul raionului șase, Rex se oprea. Nu mârâia. Nu se zbârlea. Doar se așeza, cu botul spre culoarul întunecat dintre rafturile cu canapele învelite în folie, și mă aștepta. Dacă îl trăgeam de zgardă, venea doi pași și apoi se lăsa pe spate ca un sac. Așa că raionul șapte îl făceam singur, cu lanterna, și el aștepta la capăt, cu urechile ciulite, până ieșeam pe partea cealaltă.

Mi s-a spus de la început că „e un câine ciudat, nu-l băga în seamă”. Oamenii care spun „nu-l băga în seamă” știu, de obicei, exact ce nu vor să bagi în seamă.

Raionul șapte era, în toate privințele, identic cu celelalte. Rafturi metalice de șase metri, folie, praf, un bec care pâlpâia cum pâlpâie toate becurile din toate depozitele. Nu era mai frig. Nu mirosea altfel. Nu am văzut niciodată nimic acolo, și vreau să spun asta clar, pentru că textele de felul ăsta promit de obicei că se întâmplă ceva și apoi se întâmplă. Nu s-a întâmplat.

Și totuși, în fiecare noapte, trecând prin raionul șapte, aveam senzația foarte precisă că merg printr-o cameră în care tocmai s-a oprit o conversație. Nu că ar fi fost cineva. Că fusese. Că folia de pe canapele încă mai păstra forma unei așezări care se ridicase cu o secundă înainte să intru eu.

Am încercat să-mi explic cu lucruri de om treaz. Acustica: raionul șapte era pe mijloc, cel mai departe de pereți, deci ecoul era altul. Câinele: șoldul prost, poate căzuse acolo odată. Eu: treizeci și opt de ani, divorțat de curând, mutat într-un oraș unde nu știam pe nimeni, lucrând noaptea pentru că noaptea nu trebuia să vorbesc cu nimeni. Un om în starea aia aude conversații oprite oriunde.

Toate explicațiile erau bune. Niciuna nu-l făcea pe Rex să treacă de capătul raionului șase.

Într-o noapte de noiembrie am stat în mijlocul raionului șapte cu lanterna stinsă zece minute, ca să văd ce se întâmplă. Nu s-a întâmplat nimic. Atât de nimic, atât de perfect, încât am înțeles în sfârșit ce simțea câinele: nu frică de ceva. Frică de nimic. De un nimic complet, construit, cu rafturi.$demo$), 1,
  now() - interval '90 days', $demo$Capitolul 1: Raionul șapte$demo$, public.check_chapter_text($demo$Depozitul avea douăzeci de mii de metri pătrați, nouă raioane, un birou cu geam spre hală, un ceainic și un câine. Câinele se numea Rex, pentru că oamenii care numesc câini de pază nu au niciodată imaginație, și era un ciobănesc bătrân, cu un șold prost, care mă conducea în fiecare noapte prin toate raioanele, în ordine, cu o seriozitate de funcționar.

