-- demo-18: "Lumina de la frigider" by tudor_farasomn
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001800000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, 'lumina-de-la-frigider-demo-18',
  $demo$Lumina de la frigider$demo$, $demo$Tata se trezea în fiecare noapte la trei, bea un pahar cu apă în picioare, în lumina frigiderului, și se întorcea la culcare. Treizeci de ani n-am înțeles de ce. Acum mă trezesc și eu la trei. Două eseuri scurte despre ce facem noaptea în bucătărie, despre lucrurile pe care le moștenim fără să ni le lase nimeni și despre singura lumină din casă care nu se aprinde de la întrerupător.$demo$, 'ro',
  (select id from public.categories where slug = 'nonfiction_essays'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '37 days', now() - interval '34 days', now() - interval '39 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001800000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001800000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, array['noapte', 'tată', 'bucătărie', 'amintiri', 'eseu']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001800010000'::uuid, '00000000-0000-4000-9100-001800000000'::uuid, '00000000-0000-4000-8000-000000000102'::uuid,
  'd018c001', 1, $demo$Capitolul 1: Paharul cu apă$demo$, public.check_chapter_text($demo$Când eram copil, mă trezeam uneori noaptea și vedeam, pe sub ușa camerei mele, o lumină albăstruie, slabă, care nu venea de la niciun bec din casă. Știam ce e. Era tata, în bucătărie, cu ușa frigiderului deschisă, bând un pahar cu apă în picioare.

Nu aprindea niciodată lumina. Zicea că îl trezește de tot. Deschidea frigiderul, scotea sticla, turna în același pahar, de sticlă groasă, cu fundul verde, pe care îl ținea pe raftul de sus doar pentru asta, bea încet, punea sticla la loc, închidea ușa, și casa se făcea din nou neagră. Dura cam un minut. Se întâmpla la trei, cu o precizie pe care, mai târziu, aveam s-o recunosc în mine și s-o urăsc puțin.

L-am întrebat o dată, la vreo zece ani, de ce se trezește. A zis că așa e el. Am întrebat de ce nu bea apă înainte de culcare, să nu-i mai fie sete. A râs și a zis că nu de sete se trezește. Am întrebat atunci de ce. A zis că o să înțeleg când o să am și eu bucătărie.

Am acum bucătărie. Am și frigider, unul tăcut, modern, cu o lumină albă, rece, foarte diferită de albastrul ăla vechi. Și mă trezesc la trei. Nu la trei și ceva. La trei. Stau întins un minut, cu ochii deschiși, și apoi mă ridic, merg pe întuneric prin apartament, pe un traseu pe care îl știu cu picioarele, deschid frigiderul și beau un pahar cu apă în picioare.

Nu mi-e sete.

Am încercat ani de zile să înțeleg ce e. Am citit despre ritmul somnului, despre cortizol, despre ora lupului, cum i se zice în unele locuri orei trei dimineața. Toate explicațiile sunt corecte și niciuna nu e despre asta. Pentru că asta nu e ceva ce se întâmplă în corp. E ceva ce se întâmplă în bucătărie.

Cred că tata se ridica la trei pentru că la trei casa era a lui. Ziua era al nostru, al mamei, al serviciului, al vecinilor, al tuturor. Noaptea, un minut, în lumina frigiderului, era un om care bea apă și nu-i datora nimănui nimic. Nu era fugă. Era o mică proprietate privată în mijlocul unei vieți care se dăduse altora pe bucăți.

Nu știu dacă el ar fi spus-o așa. Nu mai pot să-l întreb. A murit cu trei ani în urmă, într-o după-amiază, deci în partea de zi a vieții lui, cea publică, cea cu lumina aprinsă. Am moștenit de la el o șurubelniță, o haină care nu mi se potrivește și ora trei. Dintre toate, pe ultima o folosesc cel mai des.$demo$), 1,
  now() - interval '37 days', $demo$Capitolul 1: Paharul cu apă$demo$, public.check_chapter_text($demo$Când eram copil, mă trezeam uneori noaptea și vedeam, pe sub ușa camerei mele, o lumină albăstruie, slabă, care nu venea de la niciun bec din casă. Știam ce e. Era tata, în bucătărie, cu ușa frigiderului deschisă, bând un pahar cu apă în picioare.

