-- demo-20: "Apă stătută, apă care pleacă" by ilinca_noaptea
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-002000000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, 'apa-statuta-apa-care-pleaca-demo-20',
  $demo$Apă stătută, apă care pleacă$demo$, $demo$Un lac de la marginea orașului căruia i se aduc lucruri pierdute, o haină rămasă pe un scaun, un feribot care pleacă la unsprezece și cincizeci fără tine. Trei poeme despre ce rămâne pe mal când apa ia tot ce i se dă.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '21 days', now() - interval '15 days', now() - interval '23 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002000000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-002000000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, array['lac', 'pierdere', 'noapte', 'haine', 'poezie']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
