-- demo-21: "Carnet de pază" by ilinca_noaptea
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-002100000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, 'carnet-de-paza-demo-21',
  $demo$Carnet de pază$demo$, $demo$Un ciclu de patru poeme scrise în orele când orașul își uită numele. O sirenă pentru nimeni, un bărbat lovit pe trotuar la 3:14, un canal căruia i se spune tot, ultima tură înainte de patru. Despre ce înseamnă să stai de pază la întunericul comun. Teme întunecate și limbaj dur, pentru 16+.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
  'drawn', 'starry', 'plum', 'gold', '16_plus', 'no_ai',
  now() - interval '58 days', now() - interval '49 days', now() - interval '60 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002100000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-002100000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, array['noapte', 'oraș', 'insomnie', 'pierdere', 'poezie']);
update public.stories
set cover_kind = 'drawn', cover_design = 'starry', cover_background = 'plum', cover_accent = 'gold'
where stories.id = '00000000-0000-4000-9100-002100000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'starry', 'plum', 'gold');
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
