-- demo-22: "Apa ține minte" by ilinca_noaptea
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-002200000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, 'apa-tine-minte-demo-22',
  $demo$Apa ține minte$demo$, $demo$Două poeme în proză despre apele care ne-au crescut. Un râu mutat într-un canal de beton, în care o fetiță a învățat să înoate cu palma bunicului sub burtă. O mare văzută o singură dată pe an, ca o mătușă îndepărtată care nu știe nimic despre tine. Despre ce păstrează apa și ce păstrăm noi.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
  'automatic', null, null, null, 'all_ages', 'no_ai',
  now() - interval '5 days', now() - interval '2 days', now() - interval '7 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002200000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-002200000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, array['apă', 'mare', 'râu', 'copilărie', 'proză poetică']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-002200010000'::uuid, '00000000-0000-4000-9100-002200000000'::uuid, '00000000-0000-4000-8000-000000000103'::uuid,
  'd022c001', 1, $demo$Lecția de înot$demo$, public.check_chapter_text($demo$Am învățat să înot într-un râu care nu mai există. L-au mutat, l-au îndreptat, l-au pus într-un canal de beton și i-au dat alt nume. Dar eu l-am învățat pe el, cu malurile lui noroioase și cu sălciile care intrau în apă până la genunchi, ca niște femei care spală rufe fără să mai aibă rufe.

Bunicul mă ținea de sub burtă cu o singură palmă și spunea: „Apa te ține dacă o lași.” Eu nu o lăsam. Dădeam din mâini ca și cum aș fi vrut să pedepsesc râul pentru că e ud. Apoi, într-o zi, palma lui n-a mai fost acolo și eu n-am aflat decât târziu, când ajunsesem deja la malul celălalt și râdeam cu gura plină de apă.

Așa învățăm tot, cred. Cineva ne ține. Cineva ne lasă fără să ne spună. Și undeva la mijloc, între palmă și mal, aflăm că pluteam de mult.

Râul acela curge acum drept, între pereți, și nu mai are sălcii. Dar când închid ochii în orice apă, în orice piscină cu clor și copii zgomotoși, simt sub burtă o palmă caldă care nu mai e și care mă ține în continuare.$demo$), 1,
