-- demo-23: "Ultima bancă de la geam" by teen_17
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-002300000000'::uuid, '00000000-0000-4000-8000-000000000002'::uuid, 'ultima-banca-de-la-geam-demo-23',
  $demo$Ultima bancă de la geam$demo$, $demo$Trei poeme din ultima bancă de la geam. Ora a șaptea, când creierul e deja în autobuz. Autobuzul 112, care e orașul în mic. O prietenă care desenează pe bancă orașe pe care le acoperă vopseaua în fiecare an și care nu se supără niciodată.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
  'drawn', 'dots', 'blush', 'plum', 'all_ages', 'no_ai',
  now() - interval '42 days', now() - interval '36 days', now() - interval '44 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002300000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-002300000000'::uuid, '00000000-0000-4000-8000-000000000002'::uuid, array['liceu', 'prieteni', 'oraș', 'autobuz', 'poezie']);
update public.stories
set cover_kind = 'drawn', cover_design = 'dots', cover_background = 'blush', cover_accent = 'plum'
where stories.id = '00000000-0000-4000-9100-002300000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'dots', 'blush', 'plum');
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-002300010000'::uuid, '00000000-0000-4000-9100-002300000000'::uuid, '00000000-0000-4000-8000-000000000002'::uuid,
  'd023c001', 1, $demo$Ora a șaptea$demo$, public.check_chapter_text($demo$La ora a șaptea creierul meu e deja în autobuz.  
Profa vorbește despre ecuații de gradul doi  
și eu mă uit cum lumina intră pieziș prin geam  
și face din praful de cretă un fel de ninsoare lentă.  

Lângă mine, Vlad desenează un robot pe caiet.  
Robotul are față tristă. Îl înțeleg.  
În spate, cineva deschide un pachet de biscuiți  
cu grija unui spărgător de seifuri.  

Afară, un porumbel stă pe pervaz și se uită la noi  
ca la un acvariu.  
Treizeci de pești în uniformă  
care așteaptă să sune ceva.  

Nu urăsc școala. Vreau să spun asta clar.  
Doar că la ora a șaptea  
toate lucrurile pe care le iubesc  
sunt în alte părți:  
sala de sport goală, cu mirosul ei de cauciuc,  
șaorma de la colț, prietenii mei, orașul întreg  
care își face treaba fără mine.  

Apoi sună.  
Și toți ne ridicăm odată,  
ca un singur animal mare  
care a stat prea mult într-o cutie.$demo$), 1,
  now() - interval '42 days', $demo$Ora a șaptea$demo$, public.check_chapter_text($demo$La ora a șaptea creierul meu e deja în autobuz.  
