select '00000000-0000-4000-9100-002400000000'::uuid, '00000000-0000-4000-8000-000000000002'::uuid, 'toate-lucrurile-prima-data-demo-24',
  $demo$Toate lucrurile prima dată$demo$, $demo$Trei poeme despre un băiat căruia i-am scris „salut” fără majusculă. Prima dată când a ținut umbrela, două ore pe treptele bibliotecii, un „văzut la 23:47” citit ca un oracol. Despre cum arată dragostea când totul se întâmplă pentru prima dată și nu știi dacă să te bucuri sau să te odihnești.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '79 days', now() - interval '73 days', now() - interval '81 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002400000000'::uuid);
