-- demo-26: "Biblioteca din stația de autobuz" by teacher
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-002600000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, 'biblioteca-din-statia-de-autobuz-demo-26',
  $demo$Biblioteca din stația de autobuz$demo$, $demo$La capătul străzii Zorilor, autobuzul vine rar și oamenii așteaptă mult. Catinca, opt ani, și bunicul ei construiesc o cutie albastră cu ușă de geam și pun în ea douăsprezece cărți. Apoi cartea cu balena dispare. O poveste caldă despre cărți care pleacă și se întorc, pentru cititori de la șapte ani în sus.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'sparkles', 'paper', 'sage', 'all_ages', 'no_ai',
  now() - interval '63 days', now() - interval '57 days', now() - interval '65 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-002600000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-002600000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, array['copii', 'cărți', 'bunici', 'cartier', 'iarnă']);
update public.stories
set cover_kind = 'drawn', cover_design = 'sparkles', cover_background = 'paper', cover_accent = 'sage'
where stories.id = '00000000-0000-4000-9100-002600000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'sparkles', 'paper', 'sage');
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-002600010000'::uuid, '00000000-0000-4000-9100-002600000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid,
  'd026c001', 1, $demo$Capitolul 1: Cutia cu geam$demo$, public.check_chapter_text($demo$În capătul străzii Zorilor era o stație de autobuz la care autobuzul venea rar. Atât de rar, încât oamenii aduceau cu ei lucruri de făcut: doamna Veta împletea, domnul Ghiță citea ziarul de la un capăt la altul și apoi îl lua de la început, iar copiii numărau mașinile. Catinca, care avea opt ani și locuia chiar vizavi, se uita la ei de la fereastră și se gândea că oamenii aceia pierd foarte mult timp.

„Nu-l pierd”, a spus bunicul Mihai, când i-a zis asta. „Îl așteaptă. E altceva.” Bunicul avea un atelier mic în garaj, plin de scânduri și de miros de lac, și putea să facă din lemn aproape orice, în afară de pâine. „Dar dacă tot așteaptă”, a continuat Catinca, „n-ar fi mai bine să aștepte cu o carte?”

Bunicul a lăsat jos rindeaua. Avea felul acela de a se uita la ea când ideea era bună și el se făcea că se mai gândește.

Două sâmbete la rând au lucrat în garaj. Au făcut o cutie cât un dulăpior de bucătărie, cu un acoperiș înclinat, ca să nu stea ploaia pe el, și cu o ușă din geam, ca să se vadă cărțile dinăuntru. Catinca a dat-o cu vopsea albastră și a scris pe ea, cu litere nu prea drepte: „Ia o carte. Lasă o carte. Sau doar citește cât aștepți.”

Apoi a venit partea grea: ce cărți să pună? Catinca a stat în fața raftului ei o după-amiază întreagă. A pus cartea cu balena, pe care o știa pe dinafară. A pus una cu ghicitori. A pus trei cărți pe care le primise de două ori, un atlas vechi al bunicului și o carte de bucate a bunicii, pentru domnul Ghiță, care spunea mereu că nu știe să facă decât ouă. Douăsprezece cărți, în total. Le-a aranjat de la cea mai mare la cea mai mică, apoi după culoare, apoi iar după mărime.

Luni dimineață, bunicul a prins cutia cu patru șuruburi de stâlpul stației, la înălțimea unui copil de opt ani, „pentru că cei mari se pot apleca”. Apoi au trecut strada și s-au uitat de la fereastră.

Doamna Veta a fost prima. A deschis ușa de geam cu două degete, ca pe o ușă de muzeu, a scos cartea de ghicitori și a început să citească în timp ce împletea. Catinca a strâns mâna bunicului atât de tare, că el a spus „au”, dar a râs.$demo$), 1,
