-- demo-30: "Signal from the Quiet Side" by sofia_cerneala
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-003000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, 'signal-from-the-quiet-side-demo-30',
  $demo$Signal from the Quiet Side$demo$, $demo$On the far side of the Moon, where no transmitter is allowed, fifteen-year-old Ilse lives with eleven astronomers and a rule she has broken in secret: a hand-built radio hidden in a storage locker, and a voice from the near side that answers her at night. When the power fails in the long lunar dark, the forbidden radio is the only thing still talking.$demo$, 'en',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'starry', 'ink', 'sky', '13_plus', 'no_ai',
  now() - interval '31 days', now() - interval '22 days', now() - interval '33 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-003000000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-003000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, array['science fiction', 'moon', 'coming of age', 'radio', 'friendship']);
update public.stories
set cover_kind = 'drawn', cover_design = 'starry', cover_background = 'ink', cover_accent = 'sky'
where stories.id = '00000000-0000-4000-9100-003000000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'starry', 'ink', 'sky');
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-003000010000'::uuid, '00000000-0000-4000-9100-003000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid,
  'd030c001', 1, $demo$Chapter 1: The Rule$demo$, public.check_chapter_text($demo$There was one rule at Quietside Station that mattered more than all the others, and it was painted on the inside of the airlock in letters as tall as Ilse's forearm: NO TRANSMISSIONS.

Everything else followed from it. The station sat in a crater on the far side of the Moon because the Moon itself, three and a half thousand kilometres of rock, stood between the great dish and the noise of Earth. Every phone, every satellite, every microwave oven on the home planet was a scream the astronomers had come here not to hear. Inside the crater the sky was quiet in a way nowhere else in the solar system was quiet, and the dish listened to things older than light.

Ilse had lived here since she was eleven. Her mother ran the array. Her father had stayed on Earth, which was a story that fitted in one sentence and did not need telling again.

She was fifteen now, the only person under thirty-eight within a hundred thousand kilometres, and she knew every corridor, every panel, every sound the station made when it breathed. She knew that Dr Okafor hummed when he was worried and that Petra in Life Support kept a cat video on a loop she thought nobody had seen. She knew the schedule of the relay satellite that passed overhead twice a day and carried their data home in a tight, encrypted burst, the only legal signal that ever left the crater.

And she knew, because she had built it, exactly where the second transmitter was.

It lived in Locker 14-C, behind the spare water filters, in a box that had once held a centrifuge. It was not much: a board scavenged from a dead sensor, a coil she had wound by hand over three weeks, an antenna that was really a length of cable fed up an unused conduit to the surface. It could reach, on a good day, about as far as the limb of the Moon, where the far side turned into the near side and the quiet ended.

That was far enough. On the near side, at a mining station called Prospect, there was someone called Jun who was sixteen and had built almost the same thing for almost the same reason, and who answered.

They talked at night, in short bursts, when the dish was pointed away and the station slept. They talked about nothing, which was the point. Jun's dog on Earth. The taste of real bread. Whether the stars looked different from a crater than from a mine.

Ilse told herself the signal was too weak to matter. She told herself this every night, in the dark, with the headset warm against her ear, and every night she believed it a little less.$demo$), 1,
