select '00000000-0000-4000-9100-003100000000'::uuid, '00000000-0000-4000-8000-000000000016'::uuid, 'nonstopul-de-pe-aleea-salcamilor-demo-31',
  $demo$Nonstopul de pe Aleea Salcâmilor$demo$, $demo$Vara dintre a unsprezecea și a douăsprezecea, Vlad ține tura de noapte la nonstopul unchiului său, între o pâine, un pachet de gumă și oamenii care nu dorm niciodată. Într-o noapte, la trei fără un sfert, intră un copil de nouă ani singur, cu banii numărați în pumn, și Vlad trebuie să decidă cât de departe merge o tură de noapte.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '68 days', now() - interval '65 days', now() - interval '70 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-003100000000'::uuid);
